#define main envelope_unused_main
#include "envelope.cpp"
#undef main
#include <sstream>
#include <unordered_map>
#include <functional>

struct Source {int a,h,s;array<int,4> e;};
struct Bits {array<uint64_t,8> b{};void set(int i){b[i/64]|=uint64_t(1)<<(i%64);}bool get(int i)const{return(b[i/64]>>(i%64))&1;}Bits operator&(const Bits&o)const{Bits v;for(int i=0;i<8;i++)v.b[i]=b[i]&o.b[i];return v;}};
array<int,4> factor_small(int s){array<int,4> e{};int ps[]={2,3,5,7};for(int j=0;j<4;j++)while(s%ps[j]==0){e[j]++;s/=ps[j];}assert(s==1);return e;}
bool greedy_factors(const vector<int>&fs,const vector<int>&caps){for(int mode=0;mode<3;mode++){vector<int>b(caps.size(),1);bool ok=1;for(int p:fs){int take=-1;for(int j=0;j<int(b.size());j++)if(b[j]<=caps[j]/p){if(take<0)take=j;else if(mode==1&&int64_t(caps[j])*b[take]<int64_t(caps[take])*b[j])take=j;else if(mode==2&&int64_t(caps[j])*b[take]>int64_t(caps[take])*b[j])take=j;}if(take<0){ok=0;break;}b[take]*=p;}if(ok)return true;}return false;}
bool pair_good(const Source&a,const Source&b,int M,int p,int q){static int ep[]={0,1,0,2,1,0},eq[]={0,0,1,0,1,2};vector<int>fs;for(int i=0;i<eq[a.h]+eq[b.h];i++)fs.push_back(q);for(int i=0;i<ep[a.h]+ep[b.h];i++)fs.push_back(p);int ps[]={2,3,5,7};for(int j=3;j>=0;j--)for(int i=0;i<a.e[j]+b.e[j];i++)fs.push_back(ps[j]);return greedy_factors(fs,{M/7,M/8,M/9});}
bool small_pack(array<int,4>e,int M,int f,int k){bool empty=1;for(int x:e)if(x)empty=0;if(empty)return true;if(k<=0)return false;int ps[]={2,3,5,7};vector<int>fs,caps;U Q=1;for(int j=3;j>=0;j--)for(int i=0;i<e[j];i++){fs.push_back(ps[j]);Q*=ps[j];}for(int j=1;j<=k;j++)caps.push_back(M/(f+j));if(greedy_factors(fs,caps))return true;if(k==1)return false;if(k==2){if(Q>U(caps[0])*caps[1])return false;function<bool(int,int)>divisor=[&](int j,int d){if(j==4)return Q/U(d)<=U(caps[1]);for(int v=0;v<=e[j]&&d<=caps[0];v++){if(divisor(j+1,d))return true;if(d>caps[0]/ps[j])break;d*=ps[j];}return false;};if(divisor(0,1))return true;}
// Independent per-prime supply outside f forbidden points.
int sum=0;for(int j=0;j<4;j++){int need=e[j],kp=need+1;for(int n=0;n<=need;n++){int have=0;for(int w=ps[j];w<=M;){have+=min(n,max(0,M/w-f));if(w>M/ps[j])break;w*=ps[j];}if(have>=need){kp=n;break;}}sum+=kp;}return sum<=k;}
bool core_small(const vector<Source>&src,const vector<int>&sel,int M,int p,int q,int z){int m=sel.size(),r=gb[z],Dp=0,Dq=0;array<int,4>E{};static int ep[]={0,1,0,2,1,0},eq[]={0,0,1,0,1,2};for(int i:sel){Dp+=ep[src[i].h];Dq+=eq[src[i].h];for(int j=0;j<4;j++)E[j]+=src[i].e[j];}int C=min(m,units(M,p,Dp)+units(M,q,Dq));if(small_pack(E,M,r,9-r-C))return true;for(int i:sel){int h=src[i].h;int Cf=min(m,1+forced_units(M,p,Dp,ep[h])+forced_units(M,q,Dq,eq[h]));auto R=E;for(int j=0;j<4;j++)R[j]-=src[i].e[j];if(small_pack(R,M,r+1,9-r-Cf))return true;}return false;}
int main(int argc,char**argv){gen(0,1);sort(sm.begin(),sm.end());ifstream in("g7_exact/two/envelope_residual.txt");ofstream out("g7_exact/two/nontrivial_unresolved.txt");int limit=argc>1?atoi(argv[1]):100000000;uint64_t configs=0,classes=0,cliques=0,closed=0,unresolved=0,nodeTotal=0;int p,q,M;array<int,6>c;bool have=bool(in>>p>>q>>M);while(have&&configs<uint64_t(limit)){vector<array<int,6>>patterns;int p0=p,q0=q,M0=M;do{for(int&i:c)in>>i;patterns.push_back(c);have=bool(in>>p>>q>>M);}while(have&&p==p0&&q==q0&&M==M0);int nextp=p,nextq=q,nextM=M;p=p0;q=q0;M=M0;configs++;array<int,6>core={1,p,q,p*p,p*q,q*q};int mh=-1;for(int h=0;h<6;h++)if(M%core[h]==0&&binary_search(sm.begin(),sm.end(),M/core[h]))mh=h;assert(mh>=0);Source mx{M,mh,M/core[mh],factor_small(M/core[mh])};vector<Source>src;for(int h=1;h<6;h++)for(int s:sm){int a=core[h]*s;if(a>M)break;if(7*a<=M)continue;Source v{a,h,s,factor_small(s)};if(a==M||!pair_good(v,mx,M,p,q))src.push_back(v);}bool changed=1;while(changed){changed=0;set<int>present;for(auto v:src)present.insert(v.a);vector<Source>next;for(auto v:src){bool ok=1;for(int k=2;k*v.a<=M;k++)if(!present.count(k*v.a)){ok=0;break;}if(ok)next.push_back(v);else changed=1;}src.swap(next);}assert(src.size()<512);nodeTotal+=src.size();vector<Bits>adj(src.size());for(int i=0;i<int(src.size());i++)for(int j=i+1;j<int(src.size());j++)if(!pair_good(src[i],src[j],M,p,q)){adj[i].set(j);adj[j].set(i);}vector<int>group[6];int maxi=-1;for(int i=0;i<int(src.size());i++){group[src[i].h].push_back(i);if(src[i].a==M)maxi=i;}Bits all;for(int i=0;i<int(src.size());i++)all.set(i);unordered_map<uint64_t,bool>coveredCache;set<vector<int>>emitted;for(auto ct:patterns){classes++;vector<int>sel;Bits avail=all;bool valid=1;for(int h=1;h<6;h++)if(int(group[h].size())<ct[h])valid=0;if(!valid)continue;if(mh){if(maxi<0||!ct[mh])continue;sel.push_back(maxi);ct[mh]--;avail=avail&adj[maxi];}
function<void(int,int,Bits)>visit=[&](int h,int start,Bits allowed){while(h<=5&&ct[h]==0){h++;start=0;}if(h==6){set<int>A;for(int i:sel)A.insert(src[i].a);for(int a:A)for(int k=2;k*a<=M;k++)if(!A.count(k*a))return;cliques++;array<int,4>E{};int Dp=0,Dq=0;static int ep[]={0,1,0,2,1,0},eq[]={0,0,1,0,1,2};for(int i:sel){for(int j=0;j<4;j++)E[j]+=src[i].e[j];Dp+=ep[src[i].h];Dq+=eq[src[i].h];}uint64_t key=ct[0];for(int e:E)key=key*64+e;key=key*16+Dp;key=key*16+Dq;auto it=coveredCache.find(key);if(it!=coveredCache.end()&&it->second){closed++;return;}if(core_small(src,sel,M,p,q,ct[0])){coveredCache[key]=true;closed++;return;}vector<int>vals(A.begin(),A.end());if(emitted.insert(vals).second){unresolved++;out<<p<<' '<<q<<' '<<M<<' '<<ct[0];for(int a:vals)out<<' '<<a;out<<'\n';}return;}
int count=0;for(int k=start;k<int(group[h].size());k++)if(allowed.get(group[h][k]))count++;if(count<ct[h])return;for(int k=start;k<int(group[h].size());k++){int i=group[h][k];if(!allowed.get(i))continue;ct[h]--;sel.push_back(i);visit(h,k+1,allowed&adj[i]);sel.pop_back();ct[h]++;}};visit(1,0,avail);}
if(configs%100==0)cerr<<"configs "<<configs<<" classes "<<classes<<" nodes "<<nodeTotal<<" cliques "<<cliques<<" closed "<<closed<<" unresolved "<<unresolved<<" current "<<p0<<' '<<q0<<' '<<M0<<'\n';
if(have){p=nextp;q=nextq;M=nextM;}
}cout<<"configs="<<configs<<" cliques="<<cliques<<" closed="<<closed<<" unresolved="<<unresolved<<'\n';}
